404	      return { decision: PolicyDecision.DENY, rule };
405	    }
406	
407	    // Start with the decision from the rule or heuristics.
408	    // If the tool call was already downgraded (e.g. by heuristics), we start there.
409	    let aggregateDecision = ruleDecision;
410	
